(() => {
      const context = document.modelContext;
      const answer = {
        href: location.href,
        userAgent: navigator.userAgent,
        modelContextType: typeof context,
        prototypeMembers: context === null || typeof context !== 'object' ? [] : Object.getOwnPropertyNames(Object.getPrototypeOf(context)),
        getToolsType: context === null || typeof context !== 'object' ? 'no-model-context' : typeof context.getTools,
      };
      if (context === null || typeof context !== 'object' || typeof context.getTools !== 'function') {
        answer.outcome = 'no-getter';
        return answer;
      }
      try {
        const listed = context.getTools();
        answer.outcome = 'returned';
        answer.isArray = Array.isArray(listed);
        answer.length = Array.isArray(listed) ? listed.length : null;
        answer.json = JSON.stringify(listed);
        answer.constructorName = listed !== null && typeof listed === 'object' ? listed.constructor?.name ?? null : null;
      } catch (error) {
        answer.outcome = 'threw';
        answer.errorName = error !== null && typeof error === 'object' ? String(error.name) : typeof error;
        answer.errorMessage = error !== null && typeof error === 'object' ? String(error.message) : String(error);
      }
      return answer;
    })()

